text = SRC.read_text(encoding="utf-8")
lines = text.split("\n")

# Trouver les lignes de début et fin de la section à remplacer
# Section commence à "Alors justement, [pause] on va commencer par la base. La base absolue."
# et finit avant "Quatrième conseil, ..." ou "[inhale] Bon, on arrive..."

start_idx = None
end_idx = None
for i, line in enumerate(lines):
    if start_idx is None and line.startswith("Alors justement, [pause] on va commencer par la base. La base absolue."):
        start_idx = i
    if start_idx is not None and end_idx is None and i > start_idx and line.startswith("Quatrième conseil"):
        end_idx = i
        break

if start_idx is None:
    print("ERREUR: section début introuvable")
    exit(1)
if end_idx is None:
    print(f"ERREUR: section fin introuvable (start={start_idx})")
    exit(1)

print(f"Remplacement lignes {start_idx+1} → {end_idx} ({end_idx-start_idx} lignes)")

new_lines = lines[:start_idx] + NEW_SECTION.split("\n") + lines[end_idx:]
SRC.write_text("\n".join(new_lines), encoding="utf-8")
print(f"Nouvelle taille : {len(new_lines)} lignes")
